<?php

declare(strict_types=1);

namespace Zana\Container\Compiled;

/**
 * Base of classes generated by ContainerCompiler. Never extend it by hand.
 *
 * @internal
 *
 * @phpstan-import-type PlanData from \Zana\Container\Internal\PlanCodec
 * @phpstan-import-type GraphData from \Zana\Container\Graph\ServiceGraph
 * @phpstan-type CompiledData array{
 *     scanned: list<array{0: string, 1: string, 2: string, 3: ?string, 4: bool, 5: ?string}>,
 *     scannedTags: array<string, list<string>>,
 *     plans: array<string, PlanData>,
 *     decoratorPlans: array<string, PlanData>,
 *     graph: GraphData
 * }
 */
abstract class CompiledContainer
{
    public const FINGERPRINT = '';

    /**
     * Precomputed plans, scan results and graph.
     *
     * @return CompiledData
     */
    abstract public static function data(): array;
}
